local function C_5()
	local script = LMG2L["LocalScript_5"];
	local boton = script.Parent	
	local gui = boton.Parent	
	local marco = gui:FindFirstChild("MarcoPrincipal") or gui:FindFirstChildOfClass("Frame")	

	boton.MouseButton1Click:Connect(function()	
	    if marco then	
	        -- Esto cambia el estado: si está abierto lo cierra, si está cerrado lo abre	
	        marco.Visible = not marco.Visible	

	        -- Opcional: Cambia el texto del botón para que sepas qué va a pasar	
	        if marco.Visible then	
	            boton.Text = "Cerrar"	
	            boton.BackgroundColor3 = Color3.fromRGB(255, 100, 100) -- Rojo al abrir	
	        else	
	            boton.Text = "Abrir"	
	            boton.BackgroundColor3 = Color3.fromRGB(100, 255, 100) -- Verde al cerrar	
	        end	
	    end	
	end)	

end;
