	local marco = boton.Parent	
	local titulo = marco:FindFirstChild("Etiqueta de texto") or marco:FindFirstChildOfClass("TextLabel")	

	boton.MouseButton1Click:Connect(function()	
	    -- Efecto de carga estilo g00byd0lan	
	    boton.Text = "LOGGING IN..."	
	    boton.BackgroundColor3 = Color3.fromRGB(50, 50, 50)	

	    print("Project g00byd0lan: Buscando vulnerabilidades...")	
	    task.wait(1)	

	    -- Aquí podrías poner un script real que quieras que se active siempre	
	    -- Por ejemplo, cargar un anti-kick básico o un Infinite Yield	
	    local success, err = pcall(function()	
	        print("Project g00byd0lan: Sistemas listos.")	
	    end)	

	    if success then	
	        boton.Text = "ACTIVE"	
	        boton.BackgroundColor3 = Color3.fromRGB(0, 255, 0)	

	        if titulo then	
	            titulo.Text = "Project g00byd0lan | ONLINE"	
	            titulo.TextColor3 = Color3.fromRGB(0, 255, 0)	
	        end	
	    else	
	        boton.Text = "ERROR"	
	        boton.BackgroundColor3 = Color3.fromRGB(255, 0, 0)	
	        warn("Fallo en la inyección: " .. tostring(err))	
	    end	
	end)	

end;
