local function C_f()
	local script = LMG2L["LocalScript_f"];
	local boton = script.Parent	
	local activado = false	

	boton.MouseButton1Click:Connect(function()	
	    local char = game.Players.LocalPlayer.Character	
	    local torso = char and (char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso"))	

	    if not torso then return end	

	    if not activado then	
	        -- Aquí va tu script de partículas	
	        local pe = Instance.new("ParticleEmitter", torso)	
	        pe.Name = "G00byAura"	
	        pe.Texture = "http://roblox.com/asset/?id=362575925"	
	        pe.VelocitySpread = 50	
	        pe.LightEmission = 1	

	        boton.Text = "Aura: ON"	
	        activado = true	
	    else	
	        if torso:FindFirstChild("G00byAura") then torso.G00byAura:Destroy() end	
	        boton.Text = "Aura: OFF"	
	        activado = false	
	    end	
	end)	

end;
task.spawn(C_f);
